    """Continue horizontal foreground bars/stripes with color 1."""
    from collections import Counter
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    fg_counts = Counter(v for row in grid for v in row if v != bg)
    if not fg_counts:
        return out
    fg = fg_counts.most_common(1)[0][0]

    # Infer an alternating stripe phase on each row when at least three
    # foreground marks support it.
    phases = {}
    for r, row in enumerate(grid):
        pos = [c for c, v in enumerate(row) if v == fg]
        opts = [(sum(c % 2 == p for c in pos), p) for p in (0, 1)]
        n, phase = max(opts)
        if n >= 3:
            phases[r] = phase

    for r, row in enumerate(grid):
        pos = [c for c, v in enumerate(row) if v == fg]
        if not pos:
            continue
        last = pos[-1]
        if last == w - 1:
            continue
        run = 0
        c = last
        while c >= 0 and row[c] == fg:
            run += 1
            c -= 1

        # A repeated 3-column motif already reaches the right edge; do not
        # mistake it for an unfinished alternating stripe.
        periodic3 = False
        if w >= 12 and last >= w - 13:
            tail = row[w - 12:]
            periodic3 = (len(tail) == 12 and tail[:3] != [bg] * 3
                        and tail[:3] != [fg] * 3
                        and all(tail[i] == tail[i % 3] for i in range(12)))
        if periodic3:
            continue

        neighbor_phases = {phases[nr] for nr in (r - 1, r + 1)
                           if nr in phases and abs(nr - r) == 1}
        # A long solid bar extends as a solid ray unless an adjacent sparse
        # stripe gives an unambiguous alternating continuation phase.
        use_stripe = False
        phase = phases.get(r)
        if run >= 7 or (run >= 2 and len(pos) >= 9):
            if len(neighbor_phases) == 1:
                inherited = next(iter(neighbor_phases))
                if inherited != (last % 2):
                    use_stripe = True
                    phase = inherited
            if not use_stripe:
                for c in range(last + 1, w):
                    if row[c] == bg:
                        out[r][c] = 1
                continue

        if phase is not None:
            for c in range(last + 1, w):
                if c % 2 == phase and row[c] == bg:
                    out[r][c] = 1
    return out

